import rospy
from typing import Type, Any, Optional, TYPE_CHECKING
from ..logger.logger import logger

if TYPE_CHECKING:
    from .node import ROS1Node


class ROS1Client:
    def __init__(
        self,
        node: "ROS1Node",
        srv_type: Type,
        service: str,
        qos_profile: int = 10,
        **kwargs,
    ):
        """
        创建ROS1服务客户端

        Args:
            node: ROS1Node实例
            srv_type: 服务类型
            service: 服务名称
            qos_profile: 队列大小（对应ROS2的qos_profile，ROS1中未使用）
            **kwargs: 其他参数传递给rospy.ServiceProxy
        """
        self._node = node
        self._srv_type = srv_type
        self._service = service
        self._client = rospy.ServiceProxy(service, srv_type, **kwargs)

    def call(self, request: Any, timeout_sec: Optional[float] = None) -> Any:
        """
        同步调用服务

        Args:
            request: 服务请求对象
            timeout_sec: 超时时间（秒），ROS1中此参数被忽略

        Returns:
            服务响应对象
        """
        try:
            return self._client(request)
        except Exception as e:
            logger.error(f"Service call failed: {e}")
            return None

    def wait_for_service(self, timeout: Optional[float] = None):
        """
        等待服务可用

        Args:
            timeout: 超时时间（秒），None表示无限等待
        """
        rospy.wait_for_service(self._service, timeout=timeout)

    @property
    def service(self) -> str:
        """获取服务名称"""
        return self._service

    @property
    def srv_type(self) -> Type:
        """获取服务类型"""
        return self._srv_type

    def destroy(self):
        """销毁客户端"""
        self._client.close()
